// Resolve carousel slides from the shared heroFile column (comma-separated filenames,
// in display order). Reuses heroFile instead of a separate slideFiles column (KISS).
// Shared-folder model: folder holds many files; the row names which ones + order.
// Fail loud on not-found / ambiguous (loud error beats wrong/partial carousel).
const spec = $('Carousel input').first().json;
const files = $input.all().map(i => i.json).filter(f => f && f.id);
let slides = spec.heroFile;
if (typeof slides === 'string') slides = slides.split(',').map(s => s.trim()).filter(Boolean);
if (!Array.isArray(slides) || slides.length === 0) throw new Error('carousel: heroFile empty (need comma-separated filenames)');
if (slides.length < 2) throw new Error('carousel: need >=2 slides in heroFile, got ' + slides.length);
if (slides.length > 10) throw new Error('carousel: max 10 slides, got ' + slides.length);

const out = [];
for (let i = 0; i < slides.length; i++) {
  const want = String(slides[i]).toLowerCase();
  const matches = files.filter(f => (f.name || '').toLowerCase() === want);
  if (matches.length === 0) throw new Error(`carousel: slide '${slides[i]}' not found in folder ${spec.driveFolderId}`);
  if (matches.length > 1) throw new Error(`carousel: ambiguous slide '${slides[i]}': ${matches.length} files share this name`);
  out.push({ json: { fileId: matches[0].id, slideIndex: i, name: matches[0].name } });
}
return out;

// All uploads succeeded (any failure throws upstream = fail loud per design).
// $input.all() preserves emit order from Resolve slides -> map in order.
const spec = $('Carousel input').first().json;
const ups = $input.all().map(i => i.json);
let slides = spec.heroFile;
if (typeof slides === 'string') slides = slides.split(',').map(s => s.trim()).filter(Boolean);
const expected = Array.isArray(slides) ? slides.length : 0;
if (ups.length !== expected) throw new Error(`carousel: fbid count ${ups.length} != expected ${expected}`);
const attached = [];
for (let i = 0; i < ups.length; i++) {
  const fbid = ups[i].id || ups[i].post_id;
  if (!fbid) throw new Error(`carousel: slide ${i} upload returned no id`);
  attached.push({ media_fbid: String(fbid) });
}
const message = String(spec.copyVi || spec.copyEn || '').slice(0, 60000);
return [{ json: { id: spec.id, rowNumber: spec.rowNumber, message, attachedMedia: JSON.stringify(attached) } }];

// Normalize FB /feed response (or error) into the shared contract results[].
const spec = $('Carousel input').first().json;
const resp = $json || {};
const results = [];
const errObj = resp.error;
const pid = resp.id || resp.post_id;
if (pid && !errObj) {
  results.push({ platform: 'facebook', ok: true, url: `https://facebook.com/${pid}`, error: null });
} else {
  let msg = 'FB carousel publish failed';
  if (errObj) msg = typeof errObj === 'string' ? errObj : (errObj.message || JSON.stringify(errObj));
  else if (resp.message) msg = resp.message;
  results.push({ platform: 'facebook', ok: false, url: null, error: ('FB carousel: ' + msg).slice(0, 300) });
}
return [{ json: { id: spec.id, rowNumber: spec.rowNumber, results } }];
